lol ok maybe not that quick 😅 We have this ring buffer in C11 atomics: one producer thread, two consumer threads (a decoder and a logger) calling ring_pop on the same ring.

```c
#define N 1024
typedef struct {
    _Atomic size_t head;   /* next slot to read  */
    _Atomic size_t tail;   /* next slot to write */
    item_t buf[N];
} ring_t;

/* called by the single producer */
bool ring_push(ring_t *r, const item_t *in) {
    size_t t = atomic_load_explicit(&r->tail, memory_order_relaxed);
    size_t h = atomic_load_explicit(&r->head, memory_order_acquire);
    if (t - h == N) return false;
    r->buf[t % N] = *in;
    atomic_store_explicit(&r->tail, t + 1, memory_order_release);
    return true;
}

/* called by BOTH consumer threads */
bool ring_pop(ring_t *r, item_t *out) {
    size_t h = atomic_load_explicit(&r->head, memory_order_relaxed);
    size_t t = atomic_load_explicit(&r->tail, memory_order_acquire);
    if (h == t) return false;
    *out = r->buf[h % N];
    atomic_store_explicit(&r->head, h + 1, memory_order_release);
    return true;
}
```

